// @pit: {"label": "Align SPY 2026 top with March 2000 top, compute stats, build charts"}
async ({ http: { request }, market: { prices }, chart: { xy }, workspace: { edit } }) => {
  const H = { "User-Agent": "Mozilla/5.0" };
  const ts = (d: string) => Math.floor(Date.parse(d) / 1000);
  const yd = async (s: string, a: string, b: string) => { const r = await request(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(s)}?period1=${ts(a)}&period2=${ts(b)}&interval=1d`, { maxBytes: 1_000_000, headers: H }); const j = JSON.parse(r.body).chart.result[0]; return j.timestamp.map((t: number, i: number) => ({ d: new Date(t * 1000).toISOString().slice(0, 10), c: j.indicators.quote[0].close[i] as number })).filter((x: any) => x.c != null) as { d: string; c: number }[]; };
  const [old, cur, fd] = await Promise.all([yd("SPY", "1997-01-01", "2003-06-30"), yd("SPY", "2023-01-01", "2026-11-17"), prices({ ticker: "SPY", startDate: "2026-09-01", endDate: "2026-11-16", interval: "day" })]);
  const fdTop = fd.data.reduce((p, x) => ((x.close ?? 0) > (p.close ?? 0) ? x : p));
  const pi0 = old.findIndex((x) => x.d === "2000-03-24"), pi1 = cur.findIndex((x) => x.d === "2026-10-06");
  const P0 = old[pi0].c, P1 = cur[pi1].c;
  const rel = (a: { c: number }[], p: number, P: number, k: number) => (a[p + k] ? Math.round((a[p + k].c / P) * 1000) / 10 : null);
  const after = cur.length - 1 - pi1; // trading days since peak
  const r1 = (x: number) => Math.round(x * 10) / 10;
  // stats
  const gain = (a: { c: number }[], p: number, k: number) => r1((a[p].c / a[p - k].c - 1) * 100);
  const firstBelow = (lvl: number) => { const i = old.slice(pi0).findIndex((x) => x.c / P0 - 1 <= lvl); return i < 0 ? null : { days: i, date: old[pi0 + i].d }; };
  const postOld = old.slice(pi0, pi0 + after + 1); const minOldEarly = Math.min(...postOld.map((x) => x.c));
  const postCur = cur.slice(pi1); const minCur = postCur.reduce((p, x) => (x.c < p.c ? x : p));
  const lowOld = old.slice(pi0).reduce((p, x) => (x.c < p.c ? x : p));
  // retest highs after the 2000 peak
  const retest = old.slice(pi0 + 1, pi0 + 200).reduce((p, x) => (x.c > p.c ? x : p));
  const stats = { peak2000: { d: "2000-03-24", c: P0 }, peak2026: { d: "2026-10-06", c: r1(P1) }, fdTop, now: cur.at(-1), daysAfter: after, ddNow: r1((cur.at(-1)!.c / P1 - 1) * 100), dd2000SameDay: r1((old[pi0 + after].c / P0 - 1) * 100), dd2000SameDayDate: old[pi0 + after].d,
    worst2000inWindow: r1((minOldEarly / P0 - 1) * 100), worst2026: { d: minCur.d, pct: r1((minCur.c / P1 - 1) * 100) },
    runup250: { y2000: gain(old, pi0, 250), y2026: gain(cur, pi1, 250) }, runup500: { y2000: gain(old, pi0, 500), y2026: gain(cur, pi1, 500) },
    first5: firstBelow(-0.05), first10: firstBelow(-0.1), first20: firstBelow(-0.2), first30: firstBelow(-0.3), low: { d: lowOld.d, pct: r1((lowOld.c / P0 - 1) * 100), days: old.indexOf(lowOld) - pi0 }, retest2000: { d: retest.d, pct: r1((retest.c / P0 - 1) * 100) } };
  const src = ["https://finance.yahoo.com/quote/SPY/history", fd.url];
  // Chart A: 1 year before to now, every 5 trading days, peak=100
  const step = 5; const ksA: number[] = []; for (let k = -250; k <= after; k += step) ksA.push(k); if (ksA.at(-1) !== after) ksA.push(after); if (!ksA.includes(0)) { ksA.push(0); ksA.sort((a, b) => a - b); }
  const lab = (k: number) => (k === 0 ? "Peak" : `${k > 0 ? "+" : ""}${k}d`);
  const cA = await xy({ title: "SPY aligned on its top: 24 Mar 2000 vs 6 Oct 2026 (peak close = 100)", x: ksA.map(lab), series: [{ name: "SPY around the 24 Mar 2000 top", values: ksA.map((k) => rel(old, pi0, P0, k)) }, { name: "SPY around the 6 Oct 2026 top", values: ksA.map((k) => rel(cur, pi1, P1, k)) }], yLabel: "% of peak close", scale: "none", decimals: 1, maxPoints: 60, source: src });
  // Chart B: zoom 60 days before to now, daily
  const ksB: number[] = []; for (let k = -60; k <= after; k++) ksB.push(k);
  const cB = await xy({ title: "Zoom: 60 trading days before each top to today (+" + after + "d)", x: ksB.map(lab), series: [{ name: "SPY 2000", values: ksB.map((k) => rel(old, pi0, P0, k)) }, { name: "SPY 2026", values: ksB.map((k) => rel(cur, pi1, P1, k)) }], yLabel: "% of peak close", scale: "none", decimals: 1, maxPoints: 90, source: src });
  // Chart C: what came after 2000, to the Oct 2002 low, with today's level
  const endC = stats.low.days + 20; const ksC: number[] = []; for (let k = -250; k <= endC; k += 10) ksC.push(k); if (!ksC.includes(0)) { ksC.push(0); ksC.sort((a, b) => a - b); }
  const cC = await xy({ title: "The road after the 2000 top: SPY to the Oct 2002 low (peak close = 100)", x: ksC.map(lab), series: [{ name: "SPY 1999–2002", values: ksC.map((k) => rel(old, pi0, P0, k)) }, { name: `SPY today vs its 6 Oct 2026 top (${stats.ddNow}%)`, values: ksC.map(() => r1(100 + stats.ddNow)) }], yLabel: "% of peak close", scale: "none", decimals: 0, maxPoints: 90, source: src[0] });
  // CSV of aligned data
  const rows = ["offset_trading_days,date_2000,spy_2000_close,pct_of_peak_2000,date_2026,spy_2026_close,pct_of_peak_2026"];
  for (let k = -500; k <= stats.low.days + 20; k++) { const o = old[pi0 + k], c = cur[pi1 + k]; rows.push([k, o?.d ?? "", o?.c?.toFixed(4) ?? "", rel(old, pi0, P0, k) ?? "", c?.d ?? "", c?.c?.toFixed(2) ?? "", rel(cur, pi1, P1, k) ?? ""].join(",")); }
  await edit("docs/research/data/spy-peak-aligned-daily.csv", { revision: null, changes: [{ kind: "replaceFile", content: rows.join("\n") + "\n" }] });
  await edit("/tmp/peakcharts.json", { revision: null, changes: [{ kind: "replaceFile", content: JSON.stringify({ a: cA.markdown, b: cB.markdown, c: cC.markdown, stats }) }] });
  return { stats, pts: [cA.points, cB.points, cC.points], dropped: [cA.dropped, cB.dropped, cC.dropped] } as PitJsonValue;
}
